import{_ as e,o as s,c as a,a2 as i}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Test-Design Skill Spec","description":"","frontmatter":{},"headers":[],"relativePath":"SKILL-DESIGN.md","filePath":"SKILL-DESIGN.md"}'),n={name:"SKILL-DESIGN.md"};function o(r,t,l,d,c,p){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="test-design-skill-spec" tabindex="-1">Test-Design Skill Spec <a class="header-anchor" href="#test-design-skill-spec" aria-label="Permalink to &quot;Test-Design Skill Spec&quot;">​</a></h1><blockquote><p><a href="./SKILL-DESIGN">🇬🇧 English</a> • <a href="./SKILL-DESIGN.ja">🇯🇵 日本語</a></p></blockquote><p>How kiwa structures <strong>Claude Code skills for automating and standardizing test design</strong> across contract (Foundry / Hardhat) and dApp e2e (Playwright + kiwa fixture) layers. This document is the single source of truth referenced by Phase E implementation PRs.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>Test design is split into 3 layers:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Skill (planned)</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>1. Generic test design</strong></td><td><code>/kiwa-design</code></td><td>Given a feature spec / API / screen / code / DB schema, produce risk list, test viewpoints, test cases, priorities, automation policy</td></tr><tr><td><strong>2. Test-runner specialization</strong></td><td><code>/kiwa-forge</code>, <code>/kiwa-hardhat</code>, <code>/kiwa-play</code> (refactor)</td><td>Convert Layer 1 output into actual <code>*.t.sol</code> / <code>*.test.ts</code> / <code>*.spec.ts</code> files</td></tr><tr><td><strong>3. Documentation</strong></td><td>docs cookbook + skill reference</td><td>Show how to chain the layers for a complete dApp test pyramid</td></tr></tbody></table><p>A single user-facing skill invocation walks the full 5-step flow:</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[Skill invocation] --&gt; B[Organize input]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt; C[Identify quality risks]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; D[Select test viewpoints]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  D --&gt; E[Generate test cases]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E --&gt; F[Prioritize]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  F --&gt; G[Decide automation strategy]</span></span></code></pre></div><hr><h2 id="why-this-spec-exists" tabindex="-1">Why this spec exists <a class="header-anchor" href="#why-this-spec-exists" aria-label="Permalink to &quot;Why this spec exists&quot;">​</a></h2><p>Test design is fundamentally a <strong>specification activity</strong>, not a coding activity. The team would lose hours per feature if every developer rewrote &quot;what to test&quot; from scratch.</p><p>kiwa already proved that test-spec-first design (<code>Step 1.5</code> in <code>/kiwa-play</code>) reduces false positives and accelerates implementation. Phase E generalizes that pattern across <strong>contract / integration / e2e</strong> layers and across <strong>Foundry / Hardhat / Playwright</strong> runners.</p><p>Phase E does not invent new test taxonomy. It standardizes how Claude Code skills emit:</p><ul><li>Risk-based test selection</li><li>Viewpoint coverage (normal / abnormal / boundary / state-transition / permission / validation / idempotency / concurrency / performance / security)</li><li>Test cases in a uniform <code>TC-XXX</code> table</li><li>Priority (high / medium / low) by impact criteria</li><li>Automation recommendation (auto / manual + tooling)</li></ul><h2 id="_5-step-skill-flow" tabindex="-1">5-step skill flow <a class="header-anchor" href="#_5-step-skill-flow" aria-label="Permalink to &quot;5-step skill flow&quot;">​</a></h2><p>Every test-design skill produces the following sections <strong>in this order</strong>.</p><h3 id="_1-organize-input" tabindex="-1">1. Organize input <a class="header-anchor" href="#_1-organize-input" aria-label="Permalink to &quot;1. Organize input&quot;">​</a></h3><p>The skill must enumerate, for the target feature:</p><ul><li>Feature name + one-sentence summary</li><li>User actions (UI / CLI / API client perspective)</li><li>API contract (HTTP method / path / request / response)</li><li>DB updates (tables touched, columns mutated, transaction boundary)</li><li>Permission model (roles, scopes, multi-tenant isolation)</li><li>External integrations (third-party APIs, blockchain RPC, webhooks)</li><li>Failure modes (timeouts, retries, partial state, idempotency keys)</li></ul><p>If any of the above is missing from the spec, list it under <strong>&quot;insufficient spec&quot;</strong> in the output. The skill must not invent missing values.</p><h3 id="_2-identify-quality-risks" tabindex="-1">2. Identify quality risks <a class="header-anchor" href="#_2-identify-quality-risks" aria-label="Permalink to &quot;2. Identify quality risks&quot;">​</a></h3><p>For each input element, score the risk by 5 criteria (high / medium / low for each):</p><table tabindex="0"><thead><tr><th>Criterion</th><th>High example</th></tr></thead><tbody><tr><td>Revenue impact</td><td>Checkout / billing / settlement</td></tr><tr><td>Security impact</td><td>Auth bypass, signature forgery</td></tr><tr><td>Data destruction risk</td><td>Irreversible write, no soft delete</td></tr><tr><td>Usage frequency</td><td>Every page load, every transaction</td></tr><tr><td>Past incident history</td><td>Bug filed in the last 6 months</td></tr></tbody></table><p>The skill emits a <strong>risk summary table</strong> and feeds it into Step 3.</p><h3 id="_3-select-test-viewpoints" tabindex="-1">3. Select test viewpoints <a class="header-anchor" href="#_3-select-test-viewpoints" aria-label="Permalink to &quot;3. Select test viewpoints&quot;">​</a></h3><p>For each feature, select applicable viewpoints from the 10-item catalog:</p><table tabindex="0"><thead><tr><th>#</th><th>Viewpoint</th><th>Apply when</th></tr></thead><tbody><tr><td>1</td><td>Happy path</td><td>Always</td></tr><tr><td>2</td><td>Failure path</td><td>Any external dependency exists</td></tr><tr><td>3</td><td>Boundary value</td><td>Numeric input, string length, time range</td></tr><tr><td>4</td><td>State transition</td><td>State machine, status field, finite states</td></tr><tr><td>5</td><td>Permission</td><td>Auth-gated routes, role-based UI</td></tr><tr><td>6</td><td>Input validation</td><td>User-typed input, API payload</td></tr><tr><td>7</td><td>Idempotency</td><td>Webhook handler, payment flow, blockchain tx</td></tr><tr><td>8</td><td>Concurrency</td><td>Race conditions, multi-tab, multi-user</td></tr><tr><td>9</td><td>Performance</td><td>High-traffic endpoint, large payload</td></tr><tr><td>10</td><td>Security</td><td>Auth, signing, encryption, secret handling</td></tr></tbody></table><p>Selected viewpoints become test-case categories in Step 4.</p><h3 id="_4-generate-test-cases" tabindex="-1">4. Generate test cases <a class="header-anchor" href="#_4-generate-test-cases" aria-label="Permalink to &quot;4. Generate test cases&quot;">​</a></h3><p>Each test case is one row in the unified output table:</p><table tabindex="0"><thead><tr><th>Field</th><th>Content</th></tr></thead><tbody><tr><td>Test ID</td><td><code>TC-001</code></td></tr><tr><td>Test level</td><td>Unit / Integration / E2E</td></tr><tr><td>Viewpoint</td><td>Boundary value</td></tr><tr><td>Precondition</td><td>User logged in</td></tr><tr><td>Input</td><td>Name string at exact character limit</td></tr><tr><td>Steps</td><td>Call <code>PUT /api/profile</code> with the input</td></tr><tr><td>Expected</td><td>200 OK, DB stores correctly normalized value</td></tr><tr><td>Priority</td><td>High</td></tr><tr><td>Automation</td><td>Recommended</td></tr></tbody></table><p>The skill emits one such row per case. Cases are grouped by viewpoint and sorted by priority within each group.</p><h3 id="_5-prioritize-automation-strategy" tabindex="-1">5. Prioritize + automation strategy <a class="header-anchor" href="#_5-prioritize-automation-strategy" aria-label="Permalink to &quot;5. Prioritize + automation strategy&quot;">​</a></h3><p>Priority assignment is based on the risk summary from Step 2 + the viewpoint from Step 3:</p><ul><li><strong>High</strong>: Any cell scored &quot;high&quot; in revenue / security / data destruction</li><li><strong>Medium</strong>: At least one &quot;high&quot; in frequency / past incidents</li><li><strong>Low</strong>: All criteria &quot;low&quot;</li></ul><p>Automation defaults by test level:</p><ul><li><strong>Unit tests</strong>: Always automate (fast feedback, deterministic)</li><li><strong>Integration tests</strong>: Automate the primary API paths, skip exhaustive edge cases unless production-critical</li><li><strong>E2E tests</strong>: Automate only the critical user flows (login, checkout, on-chain transaction), defer rarely-used flows to manual verification</li></ul><p>The skill&#39;s final output appends:</p><ul><li>&quot;Tests recommended for automation&quot; — sorted by priority</li><li>&quot;Tests okay for manual verification&quot; — explanation per case</li><li>&quot;Insufficient spec&quot; — bullets the skill could not resolve</li></ul><h2 id="output-format" tabindex="-1">Output format <a class="header-anchor" href="#output-format" aria-label="Permalink to &quot;Output format&quot;">​</a></h2><p>Every test-design skill emits this markdown skeleton:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Target feature</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Spec summary</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Main quality risks</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Recommended test composition</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Test viewpoints</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Test cases</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Tests recommended for automation</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Tests okay for manual verification</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Insufficient spec</span></span></code></pre></div><p>These 9 sections are mandatory. Order is fixed. Skills must produce empty <code>(none)</code> placeholders rather than omit sections.</p><h2 id="layer-2-specialization" tabindex="-1">Layer 2 specialization <a class="header-anchor" href="#layer-2-specialization" aria-label="Permalink to &quot;Layer 2 specialization&quot;">​</a></h2><p>When Layer 1 (<code>/kiwa-design</code>) finishes, Layer 2 skills convert the generic output into runner-specific code:</p><table tabindex="0"><thead><tr><th>Layer 2 skill</th><th>Conversion target</th></tr></thead><tbody><tr><td><code>/kiwa-forge</code></td><td><code>test/*.t.sol</code> files, <code>forge test</code> execution, <code>forge coverage</code> evaluation</td></tr><tr><td><code>/kiwa-hardhat</code></td><td><code>test/*.test.ts</code> files, <code>npx hardhat test</code> execution, <code>hardhat-coverage</code> evaluation</td></tr><tr><td><code>/kiwa-play</code> (refactored)</td><td><code>tests/*.spec.ts</code> + <code>tests/prepare-env.ts</code>, Playwright execution, 4-round flake check</td></tr></tbody></table><p>Each Layer 2 skill consumes a Layer 1 spec file (<code>.context/spec/test-spec-{module}.md</code>) and writes implementation. The Layer 1 spec acts as the contract between design and implementation.</p><h2 id="skill-prompt-template" tabindex="-1">Skill prompt template <a class="header-anchor" href="#skill-prompt-template" aria-label="Permalink to &quot;Skill prompt template&quot;">​</a></h2><p>All test-design skills use this skeleton in <code>SKILL.md</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You are a specialist in application test design.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Given the inputs (spec, code, API definitions, screen layouts), identify quality risks and produce a complete test plan.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Always perform these steps:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Summarize the spec.</span></span>
<span class="line"><span>2. Identify quality risks.</span></span>
<span class="line"><span>3. Classify into unit / integration / E2E layers.</span></span>
<span class="line"><span>4. Cover viewpoints: normal / abnormal / boundary / state transition / permission / security / performance / regression.</span></span>
<span class="line"><span>5. For each test case emit: precondition, input, steps, expected outcome, priority, automation recommendation.</span></span>
<span class="line"><span>6. Flag any spec gaps that prevent confident testing.</span></span>
<span class="line"><span>7. Sort output by priority, high first.</span></span></code></pre></div><p>Layer 2 skills extend the prompt with runner-specific instructions (e.g. &quot;convert Layer 1 cases into Foundry <code>forge test</code> patterns including invariant / fuzz where viewpoint = boundary&quot;).</p><h2 id="use-cases-this-serves" tabindex="-1">Use cases this serves <a class="header-anchor" href="#use-cases-this-serves" aria-label="Permalink to &quot;Use cases this serves&quot;">​</a></h2><p>The same 9-section output covers all four review activities:</p><table tabindex="0"><thead><tr><th>Activity</th><th>How the spec helps</th></tr></thead><tbody><tr><td>Design review</td><td>Reviewers verify the test plan before implementation starts</td></tr><tr><td>Pre-implementation review</td><td>TDD-style &quot;write tests first&quot; works directly from the spec</td></tr><tr><td>PR review</td><td>Reviewer checks that the PR covers all High-priority cases</td></tr><tr><td>QA viewpoint check</td><td>QA team has a categorized checklist instead of ad-hoc exploration</td></tr></tbody></table><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Scope</th><th>Target file</th></tr></thead><tbody><tr><td><strong>E-1</strong></td><td>SKILL-DESIGN.md spec (this document)</td><td><code>docs/SKILL-DESIGN.md</code></td></tr><tr><td><strong>E-2</strong></td><td><code>/kiwa-design</code> skill (Layer 1)</td><td><code>.claude/skills/kiwa-design/</code></td></tr><tr><td><strong>E-3</strong></td><td><code>/kiwa-play</code> refactor (Layer 2 e2e)</td><td>Existing skill, integrate Layer 1</td></tr><tr><td><strong>E-4</strong></td><td><code>/kiwa-forge</code> skill</td><td><code>.claude/skills/kiwa-forge/</code></td></tr><tr><td><strong>E-5</strong></td><td><code>/kiwa-hardhat</code> skill</td><td><code>.claude/skills/kiwa-hardhat/</code></td></tr><tr><td><strong>E-6</strong></td><td>Cookbook chapter linking the layers</td><td><code>docs/{ja,en}/cookbook/kiwa-design-flow.md</code></td></tr></tbody></table><p>Phases are sequenced D → A → B style: spec → most valuable skill (Layer 1) → integration into the existing e2e skill, then community contributions for Foundry / Hardhat runners.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>Test execution scheduling (CI integration is left to the user&#39;s CI tool)</li><li>Mutation testing or formal verification (separate tooling)</li><li>Test data generation libraries (use faker / fast-check / fuzz harnesses as the user prefers)</li><li>Cross-skill memory / state (each skill invocation is stateless except for the optional <code>.context/spec/</code> artifact)</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./MOCK-DESIGN"><code>docs/MOCK-DESIGN.md</code></a> — Wallet / SDK mock fidelity spec (related concept for &quot;what to fake&quot;)</li><li><a href="./../.claude/skills/kiwa-play/SKILL"><code>.claude/skills/kiwa-play/SKILL.md</code></a> — Existing e2e skill that already follows part of this flow</li><li><a href="./../.claude/skills/kiwa-play/references/adversarial-pitfalls"><code>.claude/skills/kiwa-play/references/adversarial-pitfalls.md</code></a> — Self-check checklist for false positives</li></ul>`,61)])])}const g=e(n,[["render",o]]);export{u as __pageData,g as default};
